using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService(HttpClient httpClient) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetShipmentsAsync(ShipmentStatus? statusFilter = null)
    {
        var url = "/api/shipments";
        if (statusFilter.HasValue)
            url += $"?status={statusFilter.Value}";
        return await httpClient.GetFromJsonAsync<List<ShipmentDto>>(url) ?? [];
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        try
        {
            return await httpClient.GetFromJsonAsync<ShipmentDto>($"/api/shipments/track/{trackingNumber}");
        }
        catch (HttpRequestException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return null;
        }
    }

    public async Task<ShipmentDto> CreateShipmentAsync(CreateShipmentRequest request)
    {
        var response = await httpClient.PostAsJsonAsync("/api/shipments", request);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<ShipmentDto>())!;
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        var response = await httpClient.PutAsJsonAsync($"/api/shipments/{id}/status", new { Status = newStatus });
        response.EnsureSuccessStatusCode();
    }
}
