using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetShipmentsAsync(ShipmentStatus? statusFilter = null)
    {
        var query = db.Shipments.AsQueryable();
        if (statusFilter.HasValue)
            query = query.Where(s => s.Status == statusFilter.Value);

        return await query
            .OrderByDescending(s => s.CreatedDate)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment is null ? null : ToDto(shipment);
    }

    public async Task<ShipmentDto> CreateShipmentAsync(CreateShipmentRequest request)
    {
        var shipment = new Shipment
        {
            TrackingNumber = GenerateTrackingNumber(),
            Origin = request.Origin,
            Destination = request.Destination,
            RecipientName = request.RecipientName,
            SenderName = request.SenderName,
            WeightKg = request.WeightKg,
            Notes = request.Notes,
            Status = ShipmentStatus.Pending,
            CreatedDate = DateTime.UtcNow,
            EstimatedDelivery = DateTime.UtcNow.AddDays(5)
        };

        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return ToDto(shipment);
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        var shipment = await db.Shipments.FindAsync(id)
            ?? throw new KeyNotFoundException($"Shipment {id} not found");
        shipment.Status = newStatus;
        await db.SaveChangesAsync();
    }

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString()[..8].ToUpperInvariant()}";
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status,
        CreatedDate = s.CreatedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        RecipientName = s.RecipientName,
        SenderName = s.SenderName,
        WeightKg = s.WeightKg,
        Notes = s.Notes
    };
}
