@page "/"
@inject NavigationManager Navigation

<PageTitle>ShipmentTracker — Home</PageTitle>

<div class="text-center py-5">
    <h1 class="display-4 mb-3">📦 Shipment Tracker</h1>
    <p class="lead text-muted mb-4">Track your shipments in real time. Enter your tracking number below.</p>

    <div class="row justify-content-center">
        <div class="col-md-6">
            <div class="input-group input-group-lg">
                <input type="text" class="form-control" placeholder="Enter tracking number (e.g. SHP-20260601-A1B2C3D4)"
                       @bind="trackingNumber" @bind:event="oninput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">
                    Track
                </button>
            </div>
        </div>
    </div>
</div>

<div class="row mt-5">
    <div class="col-md-4">
        <div class="card text-center p-4">
            <h5>🚚 Real-Time Tracking</h5>
            <p class="text-muted">Follow your shipment from pickup to delivery with live status updates.</p>
