{
    <div class="alert alert-info">No shipments found.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Weight</th>
                    <th>Est. Delivery</th>
                    <th>Status</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in filteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td>@s.WeightKg.ToString("F1") kg</td>
                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>
                            @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                            {
                                <div class="dropdown">
                                    <button class="btn btn-sm btn-outline-primary dropdown-toggle" data-bs-toggle="dropdown">
                                        Update
                                    </button>
                                    <ul class="dropdown-menu">
                                        @foreach (var status in GetNextStatuses(s.Status))
                                        {
                                            <li>
                                                <button class="dropdown-item" @onclick="() => UpdateStatus(s, status)">
                                                    @status
                                                </button>
                                            </li>
                                        }
                                    </ul>
                                </div>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentDto> allShipments = [];
    private string? selectedStatus;
    private string? searchText;
    private bool isLoading = true;
    private bool showCreate;
    private bool isCreating;
    private CreateShipmentRequest newShipment = new();

    private List<ShipmentDto> filteredShipments =>
        string.IsNullOrWhiteSpace(searchText)
            ? allShipments
            : allShipments.Where(s =>
                s.TrackingNumber.Contains(searchText, StringComparison.OrdinalIgnoreCase) ||
                s.RecipientName.Contains(searchText, StringComparison.OrdinalIgnoreCase) ||
                s.SenderName.Contains(searchText, StringComparison.OrdinalIgnoreCase) ||
                s.Destination.Contains(searchText, StringComparison.OrdinalIgnoreCase))
              .ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            ShipmentStatus? filter = Enum.TryParse<ShipmentStatus>(selectedStatus, out var s) ? s : null;
            allShipments = await ShipmentService.GetShipmentsAsync(filter);
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ShowCreateForm()
    {
        newShipment = new();
        showCreate = true;
    }

    private async Task CreateShipment()
    {
        isCreating = true;
        try
        {
            await ShipmentService.CreateShipmentAsync(newShipment);
            showCreate = false;
            await LoadShipments();
        }
        finally
        {
            isCreating = false;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ShipmentStatus newStatus)
    {
        await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
        await LoadShipments();
    }

    private void ClearSearch() => searchText = null;

    private static List<ShipmentStatus> GetNextStatuses(ShipmentStatus current) => current switch
    {
        ShipmentStatus.Pending => [ShipmentStatus.PickedUp, ShipmentStatus.Cancelled],
        ShipmentStatus.PickedUp => [ShipmentStatus.InTransit, ShipmentStatus.Cancelled],
        ShipmentStatus.InTransit => [ShipmentStatus.OutForDelivery, ShipmentStatus.Cancelled],
        ShipmentStatus.OutForDelivery => [ShipmentStatus.Delivered, ShipmentStatus.Cancelled],
        _ => []
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

